"""Command-line interface for pennywise."""

import argparse
import csv
import datetime
import io
import json
import re
import sys

from . import report
from .ledger import ParseError, format_amount, format_entry, parse

__all__ = ["main"]

_DATE_RE = re.compile(r"\d{4}-\d{2}-\d{2}", re.ASCII)
_TOKEN_RE = re.compile(r"\S+")


class _Unreadable(Exception):
    """The ledger file could not be read or written (exit status 2)."""


def _date_arg(text):
    try:
        if not _DATE_RE.fullmatch(text):
            raise ValueError(text)
        return datetime.date(int(text[:4]), int(text[5:7]), int(text[8:]))
    except ValueError:
        raise argparse.ArgumentTypeError(
            "invalid date %r (expected a real date as YYYY-MM-DD)" % text
        ) from None


def _build_parser():
    parser = argparse.ArgumentParser(
        prog="pennywise", description="Report where the money went from a plain-text ledger."
    )
    sub = parser.add_subparsers(dest="command", metavar="COMMAND")
    sub.required = True

    p = sub.add_parser("balance", help="print the total of all entries")
    p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")
    p.add_argument("--json", action="store_true", help="print JSON")

    p = sub.add_parser("summary", help="print totals per category or month")
    p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")
    p.add_argument("--by", choices=["category", "month"], default="category")
    p.add_argument("--json", action="store_true", help="print JSON")

    p = sub.add_parser("list", help="print entries, oldest first")
    p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")
    p.add_argument("--category", help="only this category (any case)")
    p.add_argument("--since", type=_date_arg, metavar="DATE", help="first day included")
    p.add_argument("--until", type=_date_arg, metavar="DATE", help="last day included")
    p.add_argument("--json", action="store_true", help="print JSON")

    # No option prefix characters here, so a note such as "-refund" stays a positional.
    p = sub.add_parser("add", help="append an entry to the ledger", prefix_chars="\0", add_help=False)
    p.add_argument("file", metavar="FILE")
    p.add_argument("date", metavar="DATE")
    p.add_argument("category", metavar="CATEGORY")
    p.add_argument("amount", metavar="AMOUNT")
    p.add_argument("note", metavar="NOTE", nargs="?", default="")

    p = sub.add_parser("export", help="print entries as CSV")
    p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")
    p.add_argument("--format", choices=["csv"], default="csv")
    return parser


def _read_text(path):
    try:
        if path == "-":
            buffer = getattr(sys.stdin, "buffer", None)
            if buffer is not None:
                return buffer.read().decode("utf-8")
            return sys.stdin.read()
        with open(path, "rb") as fh:
            return fh.read().decode("utf-8")
    except (OSError, UnicodeDecodeError) as exc:
        name = "standard input" if path == "-" else path
        raise _Unreadable("cannot read %s: %s" % (name, exc)) from None


def _load(path):
    entries = parse(_read_text(path))
    # Stable sort: same-day entries keep file order.
    return sorted(entries, key=lambda e: e.date)


def _entry_dict(e):
    return {
        "date": e.date.isoformat(),
        "category": e.category,
        "amount": format_amount(e.amount),
        "note": e.note,
    }


def _cmd_balance(args):
    total = format_amount(report.balance(_load(args.file)))
    return json.dumps({"balance": total}) if args.json else total


def _cmd_summary(args):
    entries = _load(args.file)
    group = report.by_category if args.by == "category" else report.by_month
    totals = group(entries)
    rows = [(name, format_amount(totals[name])) for name in sorted(totals)]
    if args.json:
        return json.dumps(dict(rows))
    return "\n".join("%s  %s" % row for row in rows)


def _cmd_list(args):
    entries = report.filter_entries(
        _load(args.file), category=args.category, since=args.since, until=args.until
    )
    if args.json:
        return json.dumps([_entry_dict(e) for e in entries])
    return "\n".join(format_entry(e) for e in entries)


def _cmd_export(args):
    out = io.StringIO()
    writer = csv.writer(out, lineterminator="\n")
    writer.writerow(["date", "category", "amount", "note"])
    for e in _load(args.file):
        d = _entry_dict(e)
        writer.writerow([d["date"], d["category"], d["amount"], d["note"]])
    return out.getvalue().rstrip("\n")


def _cmd_add(args):
    note = args.note.strip()
    if len(note.splitlines()) > 1:
        raise ParseError(1, "note must not contain a line break")
    for value, what in ((args.date, "date"), (args.category, "category"), (args.amount, "amount")):
        if not _TOKEN_RE.fullmatch(value):
            raise ParseError(1, "invalid %s %r" % (what, value))
    candidate = "%s %s %s" % (args.date, args.category, args.amount)
    if note:
        candidate += " " + note
    entry = parse(candidate)[0]
    line = format_entry(entry)
    try:
        with open(args.file, "a+b") as fh:
            fh.seek(0, io.SEEK_END)
            if fh.tell() > 0:
                fh.seek(-1, io.SEEK_END)
                needs_newline = fh.read(1) != b"\n"
                fh.seek(0, io.SEEK_END)
            else:
                needs_newline = False
            fh.write((b"\n" if needs_newline else b"") + line.encode("utf-8") + b"\n")
    except OSError as exc:
        raise _Unreadable("cannot write %s: %s" % (args.file, exc)) from None
    return line


_COMMANDS = {
    "balance": _cmd_balance,
    "summary": _cmd_summary,
    "list": _cmd_list,
    "add": _cmd_add,
    "export": _cmd_export,
}


def main(argv=None):
    """Run the command line; return the exit status (0, 1 or 2)."""
    if argv is None:
        argv = sys.argv[1:]
    try:
        args = _build_parser().parse_args(argv)
    except SystemExit as exc:
        code = exc.code
        return code if isinstance(code, int) else (0 if code is None else 2)
    try:
        output = _COMMANDS[args.command](args)
    except ParseError as exc:
        print("pennywise: %s" % exc, file=sys.stderr)
        return 1
    except _Unreadable as exc:
        print("pennywise: %s" % exc, file=sys.stderr)
        return 2
    if output != "" or args.command in ("balance", "add"):
        print(output)
    return 0
