import datetime
import unittest
from decimal import Decimal

import _support  # noqa: F401
import pennywise

D = datetime.date
TEXT = """\
2024-03-01 salary 2500.00 March pay
2024-03-02 groceries -42.50 weekly shop
2024-04-05 Rent -900
2024-04-09 groceries -10
"""


class ReportTests(unittest.TestCase):
    def setUp(self):
        self.entries = pennywise.parse(TEXT)

    def test_balance(self):
        self.assertEqual(pennywise.balance(self.entries), Decimal("1547.50"))
        self.assertIsInstance(pennywise.balance(self.entries), Decimal)

    def test_balance_empty(self):
        self.assertEqual(pennywise.balance([]), Decimal("0"))
        self.assertIsInstance(pennywise.balance([]), Decimal)

    def test_by_category(self):
        got = pennywise.by_category(self.entries)
        self.assertIsInstance(got, dict)
        self.assertEqual(
            got, {"salary": Decimal("2500"), "groceries": Decimal("-52.50"), "rent": Decimal("-900")}
        )

    def test_by_month(self):
        got = pennywise.by_month(self.entries)
        self.assertIsInstance(got, dict)
        self.assertEqual(got, {"2024-03": Decimal("2457.50"), "2024-04": Decimal("-910")})

    def test_empty_groups(self):
        self.assertEqual(pennywise.by_category([]), {})
        self.assertEqual(pennywise.by_month([]), {})

    def test_month_key_zero_padded(self):
        (e,) = pennywise.parse("2024-01-31 a 1")
        self.assertEqual(list(pennywise.by_month([e])), ["2024-01"])

    def test_filter_none_keeps_all(self):
        self.assertEqual(pennywise.filter_entries(self.entries), self.entries)
        self.assertEqual(pennywise.filter_entries([]), [])

    def test_filter_returns_new_list(self):
        self.assertIsNot(pennywise.filter_entries(self.entries), self.entries)

    def test_filter_category_case_insensitive(self):
        got = pennywise.filter_entries(self.entries, category="GroCeries")
        self.assertEqual([e.date for e in got], [D(2024, 3, 2), D(2024, 4, 9)])
        self.assertEqual(pennywise.filter_entries(self.entries, category="nope"), [])

    def test_filter_dates_inclusive(self):
        got = pennywise.filter_entries(self.entries, since=D(2024, 3, 2), until=D(2024, 4, 5))
        self.assertEqual([e.date for e in got], [D(2024, 3, 2), D(2024, 4, 5)])

    def test_filter_one_sided(self):
        self.assertEqual(len(pennywise.filter_entries(self.entries, since=D(2024, 4, 1))), 2)
        self.assertEqual(len(pennywise.filter_entries(self.entries, until=D(2024, 3, 1))), 1)

    def test_filter_keeps_order_given(self):
        rev = list(reversed(self.entries))
        got = pennywise.filter_entries(rev, category="groceries")
        self.assertEqual([e.date for e in got], [D(2024, 4, 9), D(2024, 3, 2)])

    def test_filter_combined(self):
        got = pennywise.filter_entries(self.entries, category="groceries", since=D(2024, 4, 1))
        self.assertEqual([e.date for e in got], [D(2024, 4, 9)])


if __name__ == "__main__":
    unittest.main()
