            "2024-03-01 salary 2500.00 March pay\n"
            "2024-03-02 groceries -42.50 weekly shop\n"
            "\n"
            "2024-03-05 Rent -900\n"
        )
        entries = pennywise.parse(text)
        self.assertEqual(
            [(e.date, e.category, e.amount, e.note) for e in entries],
            [
                (datetime.date(2024, 3, 1), "salary", Decimal("2500.00"), "March pay"),
                (datetime.date(2024, 3, 2), "groceries", Decimal("-42.50"), "weekly shop"),
                (datetime.date(2024, 3, 5), "rent", Decimal("-900"), ""),
            ],
        )
        self.assertIsInstance(entries[0].date, datetime.date)
        self.assertIsInstance(entries[0].amount, Decimal)

    def test_empty_text(self):
        self.assertEqual(pennywise.parse(""), [])
        self.assertEqual(pennywise.parse("\n  \n# c\n"), [])

    def test_amount_forms_equal(self):
        for amt in ("2500", "+2500", "2500.00"):
            (e,) = pennywise.parse("2024-01-01 x %s" % amt)
            self.assertEqual(e.amount, Decimal("2500"))
        (e,) = pennywise.parse("2024-01-01 x 12.5")
        self.assertEqual(e.amount, Decimal("12.5"))
        (e,) = pennywise.parse("2024-01-01 x -0.99")
        self.assertEqual(e.amount, Decimal("-0.99"))

    def test_tabs_and_runs_of_spaces(self):
        (e,) = pennywise.parse("2024-01-01\t\tfood \t -3.00\t\tbig   shop\there")
        self.assertEqual((e.category, e.amount, e.note), ("food", Decimal("-3.00"), "big   shop\there"))

    def test_note_trimmed_internal_preserved(self):
        (e,) = pennywise.parse("  2024-01-01 food 1   a  b \t \n")
        self.assertEqual(e.note, "a  b")

    def test_crlf(self):
        entries = pennywise.parse("2024-01-01 a 1 x\r\n\r\n2024-01-02 b 2\r\n")
        self.assertEqual([e.note for e in entries], ["x", ""])

    def test_bom_stripped(self):
        (e,) = pennywise.parse("\ufeff2024-01-01 a 1")
        self.assertEqual(e.category, "a")

    def test_indented_comment_ignored(self):
        self.assertEqual(pennywise.parse("   # hi\n\t# there"), [])

    def test_entry_is_frozen(self):
        (e,) = pennywise.parse("2024-01-01 a 1")
        with self.assertRaises(Exception):
            e.category = "b"

    def test_leap_day(self):
        (e,) = pennywise.parse("2024-02-29 a 1")
        self.assertEqual(e.date, datetime.date(2024, 2, 29))

    def test_file_order_kept(self):
        entries = pennywise.parse("2024-05-01 a 1\n2024-01-01 b 2\n")
        self.assertEqual([e.category for e in entries], ["a", "b"])


class ParseErrorTests(unittest.TestCase):
    def assertBad(self, text, line):
        with self.assertRaises(pennywise.ParseError) as cm:
            pennywise.parse(text)
        self.assertEqual(cm.exception.line, line)
        self.assertIn("line %d" % line, str(cm.exception))
        self.assertTrue(str(cm.exception).startswith("line %d: " % line))
        return cm.exception

    def test_is_value_error(self):
        self.assertTrue(issubclass(pennywise.ParseError, ValueError))

    def test_bad_amounts(self):
        for amt in ("12.505", "1,000.00", "abc", "1e3", ".5", "12.", "--5", "+-5", "5%"):
