        self.assertEqual(code, 0)
        self.assertEqual(out, '[{"date": "2024-03-05", "category": "rent", "amount": "-900.00", "note": ""}]\n')
        self.assertEqual(json.loads(run(["list", self.path, "--json"])[1])[0]["note"], "March pay")

    def test_json_empty(self):
        self.assertEqual(run(["list", self.path, "--json", "--category", "x"]), (0, "[]\n", ""))

    def test_no_match_prints_nothing(self):
        self.assertEqual(run(["list", self.path, "--category", "x"]), (0, "", ""))

    def test_mistyped_dates_exit_2(self):
        for opt in ("--since", "--until"):
            for bad in ("2024-02-30", "03/01/2024", "2024-3-1", "x"):
                code, out, err = run(["list", self.path, opt, bad])
                self.assertEqual((code, out), (2, ""), (opt, bad))
                self.assertTrue(err)

    def test_stdin(self):
        self.assertEqual(run(["list", "-", "--category", "rent"], stdin=LEDGER)[1], "2024-03-05 rent -900.00\n")


