class AddTests(CliBase):
    def test_add_appends_and_prints(self):
        code, out, err = run(["add", self.path, "2024-03-09", "Fun", "-12.5", "  movie night "])
        self.assertEqual((code, out, err), (0, "2024-03-09 fun -12.50 movie night\n", ""))
        self.assertEqual(self.read(), LEDGER.encode() + b"2024-03-09 fun -12.50 movie night\n")

    def test_add_creates_file(self):
        p = os.path.join(self.dir, "new.txt")
        self.assertEqual(run(["add", p, "2024-01-01", "salary", "+100"]), (0, "2024-01-01 salary 100.00\n", ""))
        self.assertEqual(self.read(p), b"2024-01-01 salary 100.00\n")

    def test_add_to_file_without_trailing_newline(self):
        p = self.write("n.txt", "2024-01-01 a 1")
        self.assertEqual(run(["add", p, "2024-01-02", "b", "2"])[0], 0)
        self.assertEqual(self.read(p), b"2024-01-01 a 1\n2024-01-02 b 2.00\n")

    def test_add_to_empty_file(self):
        p = self.write("m.txt", "")
        run(["add", p, "2024-01-02", "b", "2"])
        self.assertEqual(self.read(p), b"2024-01-02 b 2.00\n")

    def test_add_note_starting_with_dash(self):
        code, out, _ = run(["add", self.path, "2024-03-09", "x", "5", "-refund"])
        self.assertEqual((code, out), (0, "2024-03-09 x 5.00 -refund\n"))

    def test_added_line_parses_back(self):
        run(["add", self.path, "2024-03-09", "x", "5", "a  b"])
        self.assertEqual(run(["list", self.path, "--category", "x"])[1], "2024-03-09 x 5.00 a  b\n")

    def test_invalid_entries_refused_file_untouched(self):
        cases = [
            ["2024-02-30", "a", "1"],
            ["2024-3-1", "a", "1"],
            ["2024-01-01", "a", "12.505"],
            ["2024-01-01", "a", "1,000.00"],
            ["2024-01-01", "a", "abc"],
            ["2024-01-01", "a b", "1"],
            ["2024-01-01", "a 5", "x"],
            ["2024-01-01", "", "1"],
            ["2024-01-01", "a", "1", "two\nlines"],
            ["2024-01-01", "a", "-abc"],
        ]
        for case in cases:
            code, out, err = run(["add", self.path] + case)
            self.assertEqual((code, out), (1, ""), case)
            self.assertIn("line", err)
            self.assertEqual(self.read(), LEDGER.encode(), case)

    def test_invalid_entry_does_not_create_file(self):
        p = os.path.join(self.dir, "new.txt")
        self.assertEqual(run(["add", p, "2024-01-01", "a", "x"])[0], 1)
        self.assertFalse(os.path.exists(p))

    def test_add_ignores_existing_bad_contents(self):
        p = self.write("bad.txt", "garbage\n")
        self.assertEqual(run(["add", p, "2024-01-01", "a", "1"])[0], 0)
        self.assertEqual(self.read(p), b"garbage\n2024-01-01 a 1.00\n")

    def test_unwritable_target_exit_2(self):
        self.assertEqual(run(["add", self.dir, "2024-01-01", "a", "1"])[0], 2)
        missing = os.path.join(self.dir, "nodir", "f.txt")
        code, out, err = run(["add", missing, "2024-01-01", "a", "1"])
        self.assertEqual((code, out), (2, ""))
        self.assertTrue(err)

    def test_missing_args_exit_2(self):
        self.assertEqual(run(["add", self.path, "2024-01-01", "a"])[0], 2)

    def test_stdin_dash_is_a_filename_not_stdin(self):
        cwd = os.getcwd()
        os.chdir(self.dir)
        try:
            self.assertEqual(run(["add", "-", "2024-01-01", "a", "1"], stdin="")[0], 0)
            self.assertTrue(os.path.exists("-"))
        finally:
            os.chdir(cwd)


class ErrorTests(CliBase):
    def test_ledger_mistake_exit_1(self):
        p = self.write("bad.txt", "# c\n2024-01-01 a 1\n\n2024-02-30 a 1\n")
        for cmd in (["balance"], ["summary"], ["list"], ["export"], ["balance", "--json"], ["list", "--json"]):
            code, out, err = run([cmd[0], p] + cmd[1:])
            self.assertEqual((code, out), (1, ""), cmd)
            self.assertIn("line 4", err)

    def test_ledger_mistake_on_stdin(self):
        code, out, err = run(["balance", "-"], stdin="x\n")
        self.assertEqual((code, out), (1, ""))
        self.assertIn("line 1", err)

    def test_missing_file_exit_2(self):
        code, out, err = run(["balance", os.path.join(self.dir, "nope.txt")])
        self.assertEqual((code, out), (2, ""))
        self.assertTrue(err)

    def test_directory_exit_2(self):
        self.assertEqual(run(["list", self.dir])[0], 2)

    def test_undecodable_exit_2(self):
        p = self.write("b.txt", b"2024-01-01 a 1 \xff\xfe\n", binary=True)
        code, out, err = run(["balance", p])
        self.assertEqual((code, out), (2, ""))
        self.assertTrue(err)

    def test_no_command_exit_2(self):
        code, out, err = run([])
        self.assertEqual((code, out), (2, ""))
        self.assertTrue(err)

    def test_unknown_command_exit_2(self):
        self.assertEqual(run(["frobnicate", self.path])[0], 2)

    def test_unknown_option_and_missing_file_exit_2(self):
        self.assertEqual(run(["balance", self.path, "--nope"])[0], 2)
        self.assertEqual(run(["balance"])[0], 2)

    def test_help_exit_0(self):
        self.assertEqual(run(["--help"])[0], 0)

    def test_bom_and_crlf_file(self):
        p = self.write("w.txt", b"\xef\xbb\xbf2024-01-01 a 1.5\r\n2024-01-02 a 1\r\n", binary=True)
        self.assertEqual(run(["balance", p])[1], "2.50\n")

    def test_main_default_argv(self):
        import sys
        old = sys.argv
        sys.argv = ["pennywise", "balance", self.path]
        try:
            self.assertEqual(run(None)[1], "1557.50\n")
        finally:
            sys.argv = old


